    coordinator: `Katedjy Kayapo`,
    team: [`Katedjy Kayapo`, `Pody Kayapo`],
    financier: `ASSOCIACAO MEBENGOKRE YTE KAYAPO`,
    objective: `Fortalecer a cadeia sociobioeconômica da castanha-do-pará da comunidade Kayapó por meio da organização
coletiva, da coleta sustentável, da implantação de infraestrutura logística adequada (como barcos, motores e
pontos de armazenamento), da centralização da comercialização junto a fornecedores parceiros e da
realização de capacitações técnicas voltadas para boas práticas de coleta, manejo, armazenamento, gestão
comunitária e comercialização. O projeto busca consolidar um modelo de comercialização coletiva que valorize
o trabalho dos extrativistas, a qualidade do produto coletado, de forma a promover a autonomia econômica das
famílias Kayapó, ampliar as competências locais e contribuir para a conservação da floresta amazônica.`,
    startDate: `11/2025`,
    endDate: `11/2026`,
    status: `Não iniciado`,
    progress: 0,
    budgetApproved: 164285.71,
