    id: 8,
    name: `Bem Viver Quilombola`,
    org: `ARQUIA`,
    segmento: `Comunidades quilombolas`,
    code: `08-2026`,
    coordinator: `Alex de Souza Maciel`,
    team: [`Adriele da Silva dos Santos`, `Andriele Fonseca Barbosa`, `Claudiléa dos Santos Pinheiro`, `Formação: Raimundo Magno Cardoso Nascimento`, `Mayara Pinto Abreu`],
    financier: `ARQUIA`,
    objective: `a) Promover o fortalecimento institucional da Associação das Comunidades Remanescentes de Quilombo
        das Ilhas de Abaetetuba, por meio da construção e equipamentos de um espaço físico adequado para
        abrigar suas ações sociais, produtivas e formativas;
    b) Implantar e incentivar a produção de hortaliças como estratégia de segurança alimentar, geração de
        renda e valorização dos saberes e conhecimentos tradicionais;
    c) Ampliar o conhecimento dos comunitários sobre direitos quilombolas para melhorias do advocacy
        quilombola junto aos órgãos públicos e privados;
Como desdobramento da proposta, vislumbra-se a ampliação das vendas dos produtos da agricultura, do
extrativismo e demais produções das comunidades quilombolas, em pelo menos 30%, garantindo a autonomia
financeira das famílias.`,
    startDate: `01/2026`,
    endDate: `12/2026`,
    status: `Não iniciado`,
    progress: 0,
    budgetApproved: 50000.0,
    budgetExecuted: 0,
    riskLevel: `Médio`,
