    financier: `Cooperativa dos Produtores da Agricultura Familiar de Santarém (COOPAFS) Representante Legal: Lucilene da Silva Sousa Cargo: Presidente Presidente Tel.: (93) 99225-6211 E-mail: lucilenesls13@gmail.com`,
    objective: `Fortalecer o protagonismo das mulheres indígenas no contexto da agricultura familiar, por meio de
formações multidisciplinares nas próprias comunidades, assistência técnica em quintais produtivos e
incentivo à organização comunitária, visando o empoderamento feminino, o aumento do número de
associadas indígenas na COOPAFS e a valorização da agroecologia.`,
