    financier: `Associação Indígena Riktikô “Ronkô”`,
    objective: `Impulsionar o artesanato Kayapó da Aldeia Gorotire por meio de ações integradas de formação,
 construção de um espaço, estruturação produtiva, gestão institucional e valorização cultural,
 promovendo a sustentabilidade ambiental, o fortalecimento da identidade coletiva e a geração de
 renda, com a criação de uma marca própria, catálogo físico e digital, e a ampliação da
 capacidade de produção e comercialização.`,
    startDate: `11/2025`,
    endDate: `11/2026`,
