    objective: `Objetivo Geral

Fortalecer as comunidades rurais do município de Portel por meio da qualificação da produção agroecológica,
energia limpa, acesso à água potável, internet, meios de comunicação e implantação de tecnologias sociais
essenciais, para melhoria e ampliação do acesso ao mercado.

Objetivos Específicos

   1. Implantar um sistema de geração de energia solar, por meio da aquisição de um kit de placas solares.

   2. Instalar um sistemas comunitários de abastecimento de água potável.

   3. Fornecer kits de internet rural para garantir conectividade e acesso à informação.

   4. Reformar o entreposto de produção (galpão), garantindo melhores condições de armazenamento e
      escoamento.`,
